/-- Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input n](hyp:n), [the specified input m](hyp:m), [j star](goal) is the corresponding construction. -/
def jStar (d : ℕ) (alpha beta gamma : ℝ) (n m : ℕ) : ℕ :=
  Nat.ceil ((hStar d alpha beta gamma n m)^(-(max 0 (gamma/(alpha+beta)-1)))) -- @realizes Jstar(tuned grid)

/-- The numerical rate and smoothness split displayed in the published point-CATE benchmark.  Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input n](hyp:n), [kbrw benchmark rate](goal) is the corresponding construction. -/
def kbrwBenchmarkRate (d : ℕ) (alpha beta gamma : ℝ) (n : ℕ) : ℝ :=
  if (alpha+beta)/2 < ((d:ℝ)/4)/(1+(d:ℝ)/(2*gamma)) then
    (n:ℝ)^(-(1/(1+(d:ℝ)/(2*gamma)+(d:ℝ)/(4*((alpha+beta)/2)))))
  else (n:ℝ)^(-(1/(2+(d:ℝ)/gamma)))

/-- Given [the specified input Q](hyp:Q), [lambda min](goal) is the corresponding construction. -/
def lambdaMin (Q : Matrix (PolyIdx d) (PolyIdx d) ℝ) : ℝ :=
  sInf {c | ∃ v : PolyIdx d → ℝ, (∑ u, v u^2) = 1 ∧ c = ∑ u, v u * (Q.mulVec v) u}

/-- Given [the specified input k](hyp:k), [the specified input u](hyp:u), [legendre](goal) is the corresponding construction. -/
def legendre (k : ℕ) (u : ℝ) : ℝ :=
  if k = 0 then 1 else if k = 1 then Real.sqrt 12 * u else Real.sqrt 5 * (6*u^2-1/2)

/-- Triangular coefficients for a one-dimensional affine Legendre change.  Given [the specified input k](hyp:k), [the specified input j](hyp:j), [the specified input a](hyp:a), [the specified input b](hyp:b), [legendre affine coeff](goal) is the corresponding construction. -/
def legendreAffineCoeff (k j : ℕ) (a b : ℝ) : ℝ :=
  if k = 0 then (if j = 0 then 1 else 0)
  else if k = 1 then (if j = 0 then Real.sqrt 12*a else if j = 1 then b else 0)
  else (if j = 0 then Real.sqrt 5*(6*a^2+b^2/2-1/2)
    else if j = 1 then Real.sqrt 5*Real.sqrt 12*a*b else if j = 2 then b^2 else 0)

/-- Given [the specified input d](hyp:d), [the specified input h](hyp:h), [loc cube](goal) is the corresponding construction. -/
def locCube (d : ℕ) (h : ℝ) : Set (Cov d) :=
  {x | ∀ i, x i ∈ Icc (1/2-h/2) (1/2+h/2)} -- @realizes Ch(local cube) @realizes h(localization input)

/-- Given [the specified input d](hyp:d), [the specified input h](hyp:h), [loc law](goal) is the corresponding construction. -/
def locLaw (d : ℕ) (h : ℝ) : Measure (Cov d) :=
  ENNReal.ofReal (h^(-(d:ℝ))) • volume.restrict (locCube d h) -- @realizes nuh(known localization law)

/-- Given [the specified input h](hyp:h), [the specified input x](hyp:x), [macro bump](goal) is the corresponding construction. -/
def macroBump (h : ℝ) (x : Cov d) : ℝ :=
  ∏ i, flatExp (1-4*((x i-1/2)/h)^2)/flatExp 1

/-- Given [the specified input h](hyp:h), [the specified input a](hyp:a), [the specified input b](hyp:b), [the specified input theta](hyp:theta), [the specified input x](hyp:x), [marked contrast](goal) is the corresponding construction. -/
def markedContrast (h a b : ℝ) (theta : Bool) (x : Cov d) : ℝ :=
  -2 * thetaSign theta * a*b*(macroBump h x)^2 -- @realizes tautheta(compensated deterministic contrast)

/-- Given [the specified input h](hyp:h), [the specified input delta](hyp:delta), [the specified input a](hyp:a), [the specified input b](hyp:b), [the specified input theta](hyp:theta), [the specified input arm](hyp:arm), [the specified input sigma](hyp:sigma), [the specified input x](hyp:x), [marked mean](goal) is the corresponding construction. -/
def markedMean (h delta a b : ℝ) (theta arm : Bool) (sigma : SignArray d h delta) (x : Cov d) : ℝ :=
  1/2 + b*signField h delta sigma true x + thetaSign arm * markedContrast h a b theta x / 2 -- @realizes b(control amplitude)

/-- Given [the specified input h](hyp:h), [the specified input delta](hyp:delta), [the specified input a](hyp:a), [the specified input sigma](hyp:sigma), [the specified input x](hyp:x), [marked propensity](goal) is the corresponding construction. -/
def markedPropensity (h delta a : ℝ) (sigma : SignArray d h delta) (x : Cov d) : ℝ :=
  1/2 + a*signField h delta sigma false x -- @realizes a(propensity amplitude)

