/-- Given [the specified input x](hyp:x), [the specified input xp](hyp:xp), [max dist](goal) is the corresponding construction. -/
def maxDist (x xp : Cov d) : ℝ := Finset.univ.sup' (Finset.univ_nonempty : (Finset.univ : Finset (Fin (d+1))).Nonempty)
  (fun i : Fin (d+1) => if hi : i.val < d then |x ⟨i.val,hi⟩-xp ⟨i.val,hi⟩| else 0)

/-- Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input L](hyp:L), [the overlap level eps](hyp:eps), [the specified input n](hyp:n), [the specified input m](hyp:m), [minimax risk](goal) is the corresponding construction. -/
def minimaxRisk (d : ℕ) (alpha beta gamma L eps : ℝ) (n m : ℕ) : ℝ≥0∞ :=
  Causalean.Stat.minimaxValueENNReal (classRisk d alpha beta gamma L eps n m) -- @realizes R(minimax value)

/-- Given [the specified input H](hyp:H), [the specified input theta](hyp:theta), [the specified input x](hyp:x), [the specified input s](hyp:s), [mixed density](goal) is the corresponding construction. -/
def mixedDensity (H : MarkedPriors d) (theta : Bool) (x : Fin (n+m) → Cov d) (s : RecordSpins n m) : ℝ :=
  ∑ sigma, H.weight theta sigma * ∏ i, recordLikelihood (H.law theta sigma) x s i

