          have mean := ∫ (wz : W × Z), H wz ∂μ.prod ν;
          have H1 := fun w => ∫ (z : Z), H (w, z) ∂ν - mean;
          have H2 := fun z => ∫ (w : W), H (w, z) ∂μ - mean;
          have H12 := fun wz => H wz - mean - H1 wz.1 - H2 wz.2;
